const owner = String(input.owner || '').trim();
const repo = String(input.repo || '').trim();
const limit = Math.max(1, Math.min(Number(input.limit) || 5, 10));
const feed = new URL('/' + encodeURIComponent(owner) + '/' + encodeURIComponent(repo) + '/releases.atom', location.origin);
const response = await fetch(feed.href, { credentials: 'include' });
if (!response.ok) return { success: false, status: 'http_error', repository: owner + '/' + repo, httpStatus: response.status, source: response.url };
const finalPath = new URL(response.url).pathname.split('/').filter(Boolean);
const repository = finalPath.length === 3 && finalPath[2] === 'releases.atom' ? decodeURIComponent(finalPath[0]) + '/' + decodeURIComponent(finalPath[1]) : owner + '/' + repo;
const xml = new DOMParser().parseFromString(await response.text(), 'application/xml');
if (xml.querySelector('parsererror')) return { success: false, status: 'invalid_feed', repository, source: response.url };
const releases = Array.from(xml.querySelectorAll('entry'))
  .slice(0, limit)
  .map(entry => ({
    title: String(entry.querySelector('title') && entry.querySelector('title').textContent || '').trim(),
    url: String(entry.querySelector('link') && entry.querySelector('link').getAttribute('href') || ''),
    updated: String(entry.querySelector('updated') && entry.querySelector('updated').textContent || '').trim()
  }))
  .filter(item => item.title && /^https:\/\/github\.com\/.+\/releases\/tag\//.test(item.url) && item.updated);
if (!releases.length) return { success: false, status: 'empty', repository, source: response.url };
return {
  success: true,
  status: 'ok',
  repository,
  releases,
  sources: { atom: response.url, page: new URL('/' + encodeURIComponent(repository.split('/')[0]) + '/' + encodeURIComponent(repository.split('/')[1]) + '/releases', location.origin).href }
};
